class AirportSystem_AutoGenerated {
  /*find device with provided id and find staff with provided contactsid,
   *if not exist, Creates a new device in the system with provided info and set the device contacts to the staff.*/
  createDevice(
    id: number,
    name: string,
    location: string,
    contactsid: number,
  ): boolean {
    /*Definition Start*/
    let staff: Staff = l({
      logic: () =>
        getRepository(Staff).find(
          (s: any) =>
            l({
              logic: () => s.Id === contactsid,
              description: "s.Id=contactsid",
            }).build().pass,
        ),
      description: "Staff.allInstance()->any(s|s.Id=contactsid)",
    }).build().pass;
    let device: Device = l({
      logic: () =>
        getRepository(Device).find(
          (d: any) =>
            l({
              logic: () => d.Id === id,
              description: "d.Id=id",
            }).build().pass,
        ),
      description: "Device.allInstance()->any(d|d.Id=id)",
    }).build().pass;
    let cond: boolean = l({
      logic: () => StandardOPs.oclIsUndefined(device),
      description: "device.oclIsUndefined()",
    })
      .or({
        logic: () => device.Id !== id,
        description: "device.Id<>id",
      })
      .build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(staff) === false,
        description: "staff.oclIsUndefined()=false",
      })
        .and({
          logic: () => cond === true,
          description: "cond=true",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newDevice: Device;
    return l({
      execute: () => (newDevice = new Device()),
      description: "newDevice.oclIsNew()",
    })
      .and({
        execute: () => getRepository(Device).push(newDevice),
        description: "Device.allInstance()->includes(newDevice)",
      })
      .and({
        execute: () => (newDevice.Id = id),
        description: "newDevice.Id=id",
      })
      .and({
        execute: () => (newDevice.Name = name),
        description: "newDevice.Name=name",
      })
      .and({
        execute: () => (newDevice.Location = location),
        description: "newDevice.Location=location",
      })
      .and({
        execute: () => (newDevice.Contacts = staff),
        description: "newDevice.Contacts=staff",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { AirportSystem_AutoGenerated };

